import{_ as a,o,c as i,a2 as n}from"./chunks/framework.DmUgKr4u.js";const m=JSON.parse('{"title":"Área: Blue Team / Defensa","description":"Área: Blue Team / Defensa","frontmatter":{"title":"Área: Blue Team / Defensa","description":"Área: Blue Team / Defensa"},"headers":[],"relativePath":"modules/blue-team/index.md","filePath":"modules/blue-team/index.md","lastUpdated":null}'),r={name:"modules/blue-team/index.md"};function s(t,e,l,d,c,u){return o(),i("div",null,[...e[0]||(e[0]=[n('<blockquote><p>🚀 <strong>¿Eres principiante?</strong> Antes de este módulo, revisa la <strong><a href="./../00-FUNDAMENTOS/">base común del repo</a></strong> (1 carpeta atrás). El blue team opera sobre logs y eventos: necesitas base sólida de redes y SO.</p><p>Recomendado: empieza por la ruta 🛡️ <a href="./../00-FUNDAMENTOS/rutas/ruta-defensor.html">Defensor</a>.</p></blockquote><h1 id="area-blue-team-defensa" tabindex="-1">Área: Blue Team / Defensa <a class="header-anchor" href="#area-blue-team-defensa" aria-label="Permalink to &quot;Área: Blue Team / Defensa&quot;">​</a></h1><blockquote><p><strong>Rol de el área:</strong> Formar profesionales capaces de <strong>detectar, investigar y responder</strong> a ataques en entornos reales, conectando directamente con lo que hacen los equipos SOC, incident response y threat hunting en la industria.</p></blockquote><hr><h2 id="_1-proposito-de-el-area-blue-team" tabindex="-1">1. Propósito de el Área Blue Team <a class="header-anchor" href="#_1-proposito-de-el-area-blue-team" aria-label="Permalink to &quot;1. Propósito de el Área Blue Team&quot;">​</a></h2><p>Esta área complementa la ruta ofensiva (Recon, Pentesting, Red Team) con el &quot;otro lado&quot;: <strong>defensa, monitoreo, detección y respuesta</strong>.</p><p>La idea es que los estudiantes no solo aprendan a encontrar y explotar vulnerabilidades, sino también a:</p><ul><li>Entender cómo se <strong>monitoriza</strong> una infraestructura.</li><li>Diseñar y operar <strong>detecciones</strong> frente a técnicas reales (por ejemplo, usando MITRE ATT&amp;CK como mapa mental).</li><li>Investigar <strong>incidentes</strong> y trazar la historia de un ataque.</li><li>Documentar y comunicar hallazgos de forma profesional (informes, timelines, recomendaciones).</li></ul><p>El objetivo final es crear perfiles que puedan trabajar en equipos SOC, responder incidentes y hacer threat hunting de forma sólida, con mentalidad profesional y no solo &quot;de laboratorio&quot;.</p><hr><h2 id="_2-objetivos-de-aprendizaje" tabindex="-1">2. Objetivos de aprendizaje <a class="header-anchor" href="#_2-objetivos-de-aprendizaje" aria-label="Permalink to &quot;2. Objetivos de aprendizaje&quot;">​</a></h2><p>Al completar el área Blue Team, el estudiante debería ser capaz de:</p><ol><li>Explicar el <strong>rol del Blue Team</strong> y cómo se relaciona con Red Team y Purple Team dentro de una organización.</li><li>Entender los conceptos básicos de <strong>detección, monitoreo y respuesta a incidentes</strong> (SOC, SIEM, EDR, logs, alertas, playbooks).</li><li>Usar herramientas clave de análisis y monitoreo (por ejemplo, Wazuh/OSSEC, ELK/Graylog, Wireshark/tcpdump, Sysmon) en entornos de laboratorio.</li><li>Mapear actividades ofensivas (como las vistas en la ruta de Pentesting/Red Team) a <strong>técnicas MITRE ATT&amp;CK</strong> y pensar en cómo detectarlas.</li><li>Participar en el ciclo completo de un incidente básico: <strong>detección → análisis → contención → erradicación → recuperación → lecciones aprendidas</strong>.</li><li>Crear <strong>informes y timelines</strong> de incidentes con calidad profesional, listos para portafolio.</li></ol><hr><h2 id="_3-areas-clave-dentro-de-el-area" tabindex="-1">3. Áreas clave dentro de el área <a class="header-anchor" href="#_3-areas-clave-dentro-de-el-area" aria-label="Permalink to &quot;3. Áreas clave dentro de el área&quot;">​</a></h2><p>El área Blue Team se organizará en áreas temáticas que luego se traducirán en módulos y laboratorios.</p><h3 id="_3-1-fundamentos-de-defensa-y-monitoreo" tabindex="-1">3.1 Fundamentos de defensa y monitoreo <a class="header-anchor" href="#_3-1-fundamentos-de-defensa-y-monitoreo" aria-label="Permalink to &quot;3.1 Fundamentos de defensa y monitoreo&quot;">​</a></h3><ul><li>Conceptos base: Blue Team, SOC, NOC, CSIRT, CERT.</li><li>Tipos de telemetría: logs de sistema, logs de red, logs de aplicaciones, eventos de seguridad.</li><li>Visión general de SIEM, EDR, NDR y su rol en la detección.</li></ul><h3 id="_3-2-soc-analyst-monitoring" tabindex="-1">3.2 SOC Analyst / Monitoring <a class="header-anchor" href="#_3-2-soc-analyst-monitoring" aria-label="Permalink to &quot;3.2 SOC Analyst / Monitoring&quot;">​</a></h3><ul><li>Operaciones de un SOC: turnos, niveles (Tier 1/2/3), tipos de alertas.</li><li>Detección inicial: correlación de eventos, priorización de alertas, falsos positivos.</li><li>Uso básico de herramientas tipo SIEM (consultas, dashboards, reglas sencillas).</li></ul><h3 id="_3-3-incident-response" tabindex="-1">3.3 Incident Response <a class="header-anchor" href="#_3-3-incident-response" aria-label="Permalink to &quot;3.3 Incident Response&quot;">​</a></h3><ul><li>Fases del manejo de incidentes (NIST/ISO): preparación, identificación, contención, erradicación, recuperación, lecciones aprendidas.</li><li>Evidencia y cadena de custodia (a nivel básico de laboratorio).</li><li>Documentación de incidentes: timelines, impacto, acciones ejecutadas, recomendaciones.</li></ul><h3 id="_3-4-threat-hunting" tabindex="-1">3.4 Threat Hunting <a class="header-anchor" href="#_3-4-threat-hunting" aria-label="Permalink to &quot;3.4 Threat Hunting&quot;">​</a></h3><ul><li>Diferencia entre <strong>detección reactiva</strong> y <strong>búsqueda proactiva</strong>.</li><li>Hipótesis de hunting basadas en ATT&amp;CK y en conocimiento del entorno.</li><li>Uso de logs, queries y visualizaciones para buscar actividad anómala.</li></ul><h3 id="_3-5-ingenieria-de-detecciones-mitre-att-ck" tabindex="-1">3.5 Ingeniería de detecciones / MITRE ATT&amp;CK <a class="header-anchor" href="#_3-5-ingenieria-de-detecciones-mitre-att-ck" aria-label="Permalink to &quot;3.5 Ingeniería de detecciones / MITRE ATT&amp;CK&quot;">​</a></h3><ul><li>Introducción a MITRE ATT&amp;CK como catálogo de tácticas/técnicas.</li><li>Cómo traducir una técnica ofensiva (por ejemplo, ejecución remota, movimiento lateral, cred dumping) en <strong>casos de detección</strong>.</li><li>Validación de detecciones en laboratorio: simular actividad maliciosa y verificar si se genera alerta/evento.</li></ul><hr><h2 id="_4-rutas-y-roles-dentro-de-el-area" tabindex="-1">4. Rutas y roles dentro de el área <a class="header-anchor" href="#_4-rutas-y-roles-dentro-de-el-area" aria-label="Permalink to &quot;4. Rutas y roles dentro de el área&quot;">​</a></h2><p>El área Blue Team ofrecerá rutas que se conectan con roles concretos de la industria.</p><h3 id="_4-1-ruta-soc-analyst-nivel-1–2" tabindex="-1">4.1 Ruta: SOC Analyst (Nivel 1–2) <a class="header-anchor" href="#_4-1-ruta-soc-analyst-nivel-1–2" aria-label="Permalink to &quot;4.1 Ruta: SOC Analyst (Nivel 1–2)&quot;">​</a></h3><p><strong>Objetivo:</strong> Preparar al estudiante para trabajar en un SOC como analista de primer/segundo nivel.</p><p>Enfoque del camino:</p><ul><li>Comprender el flujo de alertas en un SOC.</li><li>Aprender a revisar y clasificar alertas (triage).</li><li>Trabajar con dashboards y queries sencillas en herramientas de monitoreo.</li><li>Documentar incidentes simples y escalarlos con buena comunicación.</li></ul><p>Posibles módulos/labs (a futuro):</p><ul><li>Introducción a SOC y SIEM.</li><li>Laboratorio de revisión de alertas en entorno simulado (fintech atacada).</li><li>Ejercicios de clasificación de eventos (benigno vs sospechoso vs malicioso).</li></ul><h3 id="_4-2-ruta-incident-responder" tabindex="-1">4.2 Ruta: Incident Responder <a class="header-anchor" href="#_4-2-ruta-incident-responder" aria-label="Permalink to &quot;4.2 Ruta: Incident Responder&quot;">​</a></h3><p><strong>Objetivo:</strong> Desarrollar habilidades para coordinar y ejecutar la respuesta técnica a incidentes.</p><p>Enfoque del camino:</p><ul><li>Profundizar en las fases de respuesta a incidentes.</li><li>Practicar contención y erradicación en laboratorios controlados (por ejemplo, aislar hosts, revocar credenciales, revisar persistencia).</li><li>Generar informes de incidente con enfoque técnico y ejecutivo.</li></ul><p>Posibles módulos/labs (a futuro):</p><ul><li>Laboratorio de incidente simulado (ransomware / compromiso de cuenta / movimiento lateral).</li><li>Análisis de artefactos básicos (logs, procesos, conexiones).</li><li>Construcción de un informe de incidente listo para portafolio.</li></ul><h3 id="_4-3-ruta-threat-hunter" tabindex="-1">4.3 Ruta: Threat Hunter <a class="header-anchor" href="#_4-3-ruta-threat-hunter" aria-label="Permalink to &quot;4.3 Ruta: Threat Hunter&quot;">​</a></h3><p><strong>Objetivo:</strong> Enseñar a buscar amenazas de forma proactiva usando hipótesis y datos del entorno.</p><p>Enfoque del camino:</p><ul><li>Formular hipótesis de hunting basadas en ATT&amp;CK y en la realidad del entorno (por ejemplo, una fintech como NovaPay Labs).</li><li>Diseñar consultas en herramientas de logs/telemetría.</li><li>Identificar patrones anómalos y relacionarlos con técnicas ofensivas.</li></ul><p>Posibles módulos/labs (a futuro):</p><ul><li>Hunting de ejecución sospechosa en endpoints.</li><li>Hunting de actividad anómala en autenticaciones y cuentas.</li><li>Creación de casos de hunting reutilizables (&quot;playbooks&quot; simples).</li></ul><h3 id="_4-4-ruta-deteccion-e-ingenieria-de-reglas" tabindex="-1">4.4 Ruta: Detección e Ingeniería de reglas <a class="header-anchor" href="#_4-4-ruta-deteccion-e-ingenieria-de-reglas" aria-label="Permalink to &quot;4.4 Ruta: Detección e Ingeniería de reglas&quot;">​</a></h3><p><strong>Objetivo:</strong> Conectar directamente con la experiencia de construir y ajustar detecciones.</p><p>Enfoque del camino:</p><ul><li>Usar técnicas ofensivas vistas en el área de Red Team para diseñar detecciones concretas.</li><li>Crear y ajustar reglas en herramientas como Wazuh, SIEM o plataformas similares.</li><li>Validar detecciones con pruebas de ataque controladas (Purple Team mindset).</li></ul><p>Posibles módulos/labs (a futuro):</p><ul><li>Laboratorio de creación de reglas de detección para actividad sospechosa en logs de sistema.</li><li>Mapeo de laboratorio ofensivo (por ejemplo, ataque a NovaPay Labs) a detecciones específicas.</li></ul><hr><h2 id="_5-conexion-con-otras-areaes" tabindex="-1">5. Conexión con otras áreaes <a class="header-anchor" href="#_5-conexion-con-otras-areaes" aria-label="Permalink to &quot;5. Conexión con otras áreaes&quot;">​</a></h2><p>El área Blue Team no vive aislada: está pensada para que los estudiantes vean <strong>los mismos escenarios desde ángulos diferentes</strong>.</p><ul><li><p><strong>Con Pentesting / Red Team:</strong><br> Los mismos ataques que se practican en los labs ofensivos (por ejemplo, contra la fintech NovaPay Labs) se reutilizarán como casos de estudio para detección y respuesta en Blue Team.</p></li><li><p><strong>Con Purple Team:</strong><br> Esta área sienta las bases para, en el futuro, diseñar ejercicios donde Red y Blue colaboran, validando detecciones frente a técnicas ofensivas específicas.</p></li><li><p><strong>Con AI / MLSecOps (más adelante):</strong><br> La telemetría, detecciones y playbooks que se construyan aquí pueden alimentar módulos avanzados donde se use IA para detección, priorización o automatización.</p></li></ul><hr><h2 id="_6-tipo-de-labs-y-entregables" tabindex="-1">6. Tipo de labs y entregables <a class="header-anchor" href="#_6-tipo-de-labs-y-entregables" aria-label="Permalink to &quot;6. Tipo de labs y entregables&quot;">​</a></h2><p>Al igual que en la ruta ofensiva, los laboratorios de el área Blue Team seguirán un enfoque profesional y progresivo:</p><ul><li>Labs con <strong>narrativa inmersiva</strong> (por ejemplo, incidentes y ataques contra una fintech como NovaPay Labs).</li><li>Uso de herramientas reales de la industria (Wazuh, SIEM open source, capturas de tráfico, etc.) en entornos controlados.</li><li>Entregables orientados a portafolio: <ul><li>Informes de incidente.</li><li>Timelines de eventos.</li><li>Reglas de detección (o pseudocódigo de reglas).</li><li>Casos de hunting documentados.</li></ul></li></ul><p>La progresión empezará por fundamentos claros y labs guiados, y con el tiempo dará más libertad al estudiante para investigar, plantear hipótesis y tomar decisiones de análisis por su cuenta.</p><hr><h2 id="_7-proximos-pasos" tabindex="-1">7. Próximos pasos <a class="header-anchor" href="#_7-proximos-pasos" aria-label="Permalink to &quot;7. Próximos pasos&quot;">​</a></h2><p>Los siguientes pasos para esta área podrían ser:</p><ol><li>Crear el <strong>README del primer módulo Blue Team</strong> (por ejemplo, <code>01-fundamentos-blue-team-y-soc/</code>) con objetivos claros y un primer lab muy guiado sobre lectura e interpretación de logs y alertas básicas.</li><li>Diseñar un primer <strong>lab de SOC básico</strong> reutilizando eventos/ataques simples desde la ruta ofensiva de NovaPay Labs.</li><li>Definir una plantilla de <strong>informe de incidente</strong> en <code>portafolio/</code>, similar a las plantillas de recon y pentest, pero orientada a Blue Team.</li></ol><p>A medida que se construyan los módulos, esta área se irá actualizando para reflejar las rutas y labs disponibles.</p>',67)])])}const h=a(r,[["render",s]]);export{m as __pageData,h as default};
